/* One profile photo, everywhere. profiles.avatar_url is the creator's face and every other row keeps a copy of it: onepages.avatar_url and the copy taken when the page was published, creators.avatar_url, and the creator page header's avatarUrl in store_builder_configs and product_page_configs. Part 44 moved a copy only while it still held the value the profile used to hold, so the first editor to write a copy made it 'chosen' and it never followed again: one owner had three different faces at once, one on his creator page, one in Settings and one on his OnePage. A name can honestly differ from page to page; a face cannot. This makes every copy of the PHOTO take whatever the profile says, leaves the name rule exactly as it was, and brings the copies already apart back onto one photo. An account whose profile has no photo but whose pages do, and which never chose or removed a photo itself, keeps that face: it is lifted into the profile first. Run after part 44, whose trigger and helpers it reuses. Adds no table and grants nothing. Until it runs, the app does the same work from its own routes (lib/account/profile-follow), which covers Settings, the OnePage editor, the creator page builder, the storefront's Edit profile and both onboarding flows. */
/* The photo half of part 44's follow, replaced by a mirror: a copy takes the profile's photo whatever it holds. Part 44's storelib_follow_config and its trigger both call this, so replacing it here changes every copy the trigger writes without touching the name rule (storelib_follow_text), which still leaves a page title somebody typed alone. */
CREATE OR REPLACE FUNCTION public.storelib_follow_photo(stored text, was text, now_value text) RETURNS text LANGUAGE sql IMMUTABLE AS $$ SELECT now_value $$;
/* The trigger again, in case part 44's was dropped by hand; skipped when part 44 has not run, because its function is what the trigger calls. */
DO $do$ BEGIN IF to_regprocedure('public.profiles_identity_follows()') IS NOT NULL THEN DROP TRIGGER IF EXISTS profiles_identity_follows ON public.profiles; CREATE TRIGGER profiles_identity_follows AFTER UPDATE OF display_name, avatar_url ON public.profiles FOR EACH ROW WHEN (old.display_name IS DISTINCT FROM new.display_name OR old.avatar_url IS DISTINCT FROM new.avatar_url) EXECUTE FUNCTION public.profiles_identity_follows(); END IF; END $do$;
/* Part 44's test for the account picture a sign in provider sent, again, word for word, so this part stands on its own where part 44 has not run. Replacing it with the same body changes nothing where it has. */
CREATE OR REPLACE FUNCTION public.storelib_provider_photo(url text) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$ SELECT coalesce(btrim(url) ~* '^https?://(([a-z0-9-]+\.)*googleusercontent\.com/(a|a-)/|([a-z0-9-]+\.)*googleusercontent\.com/-[^/]+/AAAAAAAAAAI/|graph\.facebook\.com/(v[0-9.]+/)?[^/]+/picture([/?]|$)|platform-lookaside\.fbsbx\.com/platform/profilepic/|pbs\.twimg\.com/profile_images/|avatars\.githubusercontent\.com/|cdn\.discordapp\.com/avatars/|media(-exp[0-9])?\.licdn\.com/dms/image/[^?]*profile-displayphoto)', false) $$;
/* The best face an account already has outside its profile: the creator page header first, because onboarding writes it and the creator page shows it, then the OnePage's. A picture a sign in provider sent is not one anybody chose and is passed over. */
CREATE OR REPLACE FUNCTION public.storelib_best_photo(uid uuid) RETURNS text LANGUAGE sql STABLE AS $$ SELECT q.photo FROM (SELECT coalesce(nullif(btrim(coalesce((SELECT s.published_config#>>'{headerSettings,avatarUrl}' FROM public.store_builder_configs s JOIN public.creators c ON c.id = s.creator_id WHERE c.user_id = uid AND s.page_type = 'shop' LIMIT 1), '')), ''), nullif(btrim(coalesce((SELECT s.draft_config#>>'{headerSettings,avatarUrl}' FROM public.store_builder_configs s JOIN public.creators c ON c.id = s.creator_id WHERE c.user_id = uid AND s.page_type = 'shop' LIMIT 1), '')), ''), nullif(btrim(coalesce((SELECT o.avatar_url FROM public.onepages o WHERE o.owner_id = uid LIMIT 1), '')), '')) AS photo) q WHERE q.photo IS NOT NULL AND NOT public.storelib_provider_photo(q.photo) $$;
/* An account with no photo in its profile and a face on its pages keeps that face, rather than losing it to the mirror below. Only for an account that never chose or removed a photo itself: the mark the app keeps on the account (storelib_avatar_chosen, lib/account/avatar) is what stops a photo somebody deleted in Settings being lifted back in from a leftover copy. */
UPDATE public.profiles p SET avatar_url = public.storelib_best_photo(p.id) WHERE nullif(btrim(coalesce(p.avatar_url, '')), '') IS NULL AND public.storelib_best_photo(p.id) IS NOT NULL AND NOT coalesce((SELECT u.raw_user_meta_data->>'storelib_avatar_chosen' = 'true' FROM auth.users u WHERE u.id = p.id), false);
/* The OnePage: its own copy and the copy taken at the last publish, which is what the live page, the tab icon and the share card are built from. */
UPDATE public.onepages o SET avatar_url = p.avatar_url, published_profile = CASE WHEN jsonb_typeof(o.published_profile) = 'object' THEN jsonb_set(o.published_profile, '{avatar_url}', coalesce(to_jsonb(p.avatar_url), 'null'::jsonb)) ELSE o.published_profile END FROM public.profiles p WHERE p.id = o.owner_id AND (o.avatar_url IS DISTINCT FROM p.avatar_url OR (jsonb_typeof(o.published_profile) = 'object' AND o.published_profile->>'avatar_url' IS DISTINCT FROM p.avatar_url));
/* The creator row, which the product page and the website's name read. */
UPDATE public.creators c SET avatar_url = p.avatar_url FROM public.profiles p WHERE p.id = c.user_id AND c.avatar_url IS DISTINCT FROM p.avatar_url;
/* The creator page header, draft and published alike. A header that never kept a photo of its own already draws the profile's and is left absent; '' is the creator page's way of saying 'show my initials', which is what a profile with no photo means. */
UPDATE public.store_builder_configs s SET draft_config = CASE WHEN s.draft_config#>>'{headerSettings,avatarUrl}' IS NOT NULL THEN jsonb_set(s.draft_config, '{headerSettings,avatarUrl}', to_jsonb(coalesce(p.avatar_url, ''))) ELSE s.draft_config END, published_config = CASE WHEN s.published_config#>>'{headerSettings,avatarUrl}' IS NOT NULL THEN jsonb_set(s.published_config, '{headerSettings,avatarUrl}', to_jsonb(coalesce(p.avatar_url, ''))) ELSE s.published_config END FROM public.creators c JOIN public.profiles p ON p.id = c.user_id WHERE c.id = s.creator_id AND ((s.draft_config#>>'{headerSettings,avatarUrl}' IS NOT NULL AND s.draft_config#>>'{headerSettings,avatarUrl}' IS DISTINCT FROM coalesce(p.avatar_url, '')) OR (s.published_config#>>'{headerSettings,avatarUrl}' IS NOT NULL AND s.published_config#>>'{headerSettings,avatarUrl}' IS DISTINCT FROM coalesce(p.avatar_url, '')));
/* And a product page's own header, where that table exists. */
DO $do$ BEGIN IF to_regclass('public.product_page_configs') IS NOT NULL THEN EXECUTE $q$ UPDATE public.product_page_configs s SET draft_config = CASE WHEN s.draft_config#>>'{headerSettings,avatarUrl}' IS NOT NULL THEN jsonb_set(s.draft_config, '{headerSettings,avatarUrl}', to_jsonb(coalesce(p.avatar_url, ''))) ELSE s.draft_config END, published_config = CASE WHEN s.published_config#>>'{headerSettings,avatarUrl}' IS NOT NULL THEN jsonb_set(s.published_config, '{headerSettings,avatarUrl}', to_jsonb(coalesce(p.avatar_url, ''))) ELSE s.published_config END FROM public.creators c JOIN public.profiles p ON p.id = c.user_id WHERE c.id = s.creator_id AND ((s.draft_config#>>'{headerSettings,avatarUrl}' IS NOT NULL AND s.draft_config#>>'{headerSettings,avatarUrl}' IS DISTINCT FROM coalesce(p.avatar_url, '')) OR (s.published_config#>>'{headerSettings,avatarUrl}' IS NOT NULL AND s.published_config#>>'{headerSettings,avatarUrl}' IS DISTINCT FROM coalesce(p.avatar_url, ''))) $q$; END IF; END $do$;
notify pgrst, 'reload schema';
